package com.oms.service;
import com.oms.config.Db;import com.oms.dao.*;import com.oms.model.*;import com.oms.security.PermissionPolicy;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;
public class RouteCollectionService {
 private final RouteCollectionDao dao=new RouteCollectionDao();private final PaymentDao payments=new PaymentDao();private final InvoiceDao invoices=new InvoiceDao();private final AuditLogDao audit=new AuditLogDao();
 public RouteCollectionDao.PageData page(User viewer)throws SQLException{Long scope=!viewer.isAdmin()&&viewer.hasRole(Role.SALES_REP)?viewer.getId():null;try(Connection c=Db.getConnection()){return dao.page(c,scope);}}
 public long record(long customerId,BigDecimal amount,LocalDate date,String receiptPath,User actor)throws SQLException{
  if(!PermissionPolicy.canTakeOrders(actor.getRoles()))throw new ForbiddenException("Bạn không có quyền ghi nhận thu tiền theo tuyến.");
  if(customerId<=0||amount==null||amount.signum()<=0||amount.stripTrailingZeros().scale()>0)throw new ServiceException("Đại lý hoặc số tiền không hợp lệ.");if(date==null||date.isAfter(LocalDate.now()))throw new ServiceException("Ngày thu không hợp lệ.");
  return Db.inTransaction(c->{Customer customer=new CustomerDao().findByIdForUpdate(c,customerId);if(customer==null)throw new ServiceException("Không tìm thấy đại lý.");if(!actor.isAdmin()&&actor.hasRole(Role.SALES_REP)&&!Objects.equals(customer.getSalesRepId(),actor.getId()))throw new ForbiddenException("Đại lý không thuộc phạm vi của bạn.");List<Payment.OpenInvoice> open=payments.openInvoices(c,customerId,true);BigDecimal debt=open.stream().map(Payment.OpenInvoice::getOutstanding).reduce(BigDecimal.ZERO,BigDecimal::add);if(amount.compareTo(debt)>0)throw new ServiceException("Không thu vượt công nợ hiện tại.");String code=String.format("PT%06d",invoices.nextNumber(c,"PAYMENT"));long paymentId=payments.insert(c,code,customerId,amount,Payment.Method.CASH,date,actor.getId(),"Thu tiền theo tuyến",actor.getId());BigDecimal left=amount;for(Payment.OpenInvoice invoice:open){if(left.signum()==0)break;BigDecimal part=left.min(invoice.getOutstanding());payments.insertAllocation(c,paymentId,invoice.getId(),part);payments.applyToInvoice(c,invoice.getId(),part);payments.reduceReceivable(c,invoice.getCode(),part);left=left.subtract(part);}long id=dao.insert(c,paymentId,receiptPath);audit.log(c,actor.getId(),"ROUTE_COLLECTION_RECORD","ROUTE_COLLECTION",id,code+" · "+customer.getCode()+" · "+amount);return id;});
 }
 public void confirm(long id,User actor)throws SQLException{if(!(actor.isAdmin()||actor.hasRole(Role.ACCOUNTANT)))throw new ForbiddenException("Chỉ kế toán được xác nhận nộp tiền.");Db.inTransaction(c->{dao.confirm(c,id,actor.getId());audit.log(c,actor.getId(),"ROUTE_COLLECTION_CONFIRM","ROUTE_COLLECTION",id,"Xác nhận tiền đã nộp công ty");return null;});}
}
